<?php
/**
 * Report skladu. Cte tabulku stock_items (od 2024 ji spravuje novy e-shop),
 * rezervace jsou JSON {"orderId": pocet}.
 */

namespace App\Legacy\lib;

class StockReport
{
    public static function all()
    {
        global $db;
        legacy_db();
        $rows = $db->query("SELECT s.product_id, s.on_hand, s.reservations, p.name, p.sku, p.active"
            . " FROM stock_items s LEFT JOIN products p ON p.id = s.product_id ORDER BY p.name");

        $out = array();
        foreach ($rows as $r) {
            $reserved = self::reservedQty($r['reservations']);
            $r['reserved'] = $reserved;
            $r['available'] = (int) $r['on_hand'] - $reserved;
            $r['low'] = $r['available'] < config('low_stock', 5);
            $out[] = $r;
        }

        return $out;
    }

    /**
     * Soucet rezervaci z JSONu.
     */
    public static function reservedQty($json)
    {
        if ($json === null || $json === '') {
            return 0;
        }
        $data = json_decode((string) $json, true);
        if (!is_array($data)) {
            return 0;
        }
        $sum = 0;
        foreach ($data as $orderId => $qty) {
            $sum += (int) $qty;
        }

        return $sum;
    }

    /**
     * Rezervace s cisly objednavek (pro detail produktu).
     */
    public static function reservations($productId)
    {
        global $db;
        legacy_db();
        $r = $db->one("SELECT reservations FROM stock_items WHERE product_id = '" . $productId . "'");
        if ($r === null) {
            return array();
        }
        $data = json_decode((string) $r['reservations'], true);

        return is_array($data) ? $data : array();
    }

    public static function lowStock()
    {
        $out = array();
        foreach (self::all() as $r) {
            if ($r['low']) {
                $out[] = $r;
            }
        }

        return $out;
    }

    /**
     * Rucni korekce skladu (inventura). Prepise on_hand primo v tabulce.
     * FIXME: novy e-shop o tom nevi, ale funguje to
     */
    public static function setOnHand($productId, $qty)
    {
        global $db;
        legacy_db();
        $db->exec("UPDATE stock_items SET on_hand = " . (int) $qty . " WHERE product_id = '" . $productId . "'");
        audit_log('stock', $productId, 'inventura', array('on_hand' => (int) $qty));
    }

    /**
     * Rezervace, jejichz objednavka uz je stornovana (visi tam).
     */
    public static function orphanReservations()
    {
        global $db;
        legacy_db();
        $out = array();
        foreach ($db->query("SELECT product_id, reservations FROM stock_items") as $r) {
            $data = json_decode((string) $r['reservations'], true);
            if (!is_array($data)) {
                continue;
            }
            foreach ($data as $orderId => $qty) {
                $o = $db->one("SELECT status FROM orders WHERE id = '" . $orderId . "'");
                if ($o === null || $o['status'] == 'cancelled') {
                    $out[] = array('product_id' => $r['product_id'], 'order_id' => $orderId, 'qty' => (int) $qty);
                }
            }
        }

        return $out;
    }
}
<?php
/**
 * Sklad. Data jsou v stock_items (spravuje novy e-shop), rezervace v JSONu.
 */

namespace App\Legacy\Admin;

use App\Legacy\lib\StockReport;

class StockController extends BaseController
{
    protected $title = 'Sklad';

    public function listAction()
    {
        global $db;
        legacy_db();

        $onlyLow = get_param('low') == '1';
        $rows = $onlyLow ? StockReport::lowStock() : StockReport::all();

        // produkty bez zaznamu ve skladu
        $missing = $db->query("SELECT p.id, p.name, p.sku FROM products p LEFT JOIN stock_items s ON s.product_id = p.id WHERE s.product_id IS NULL AND p.active = 1");

        $totalOnHand = 0;
        $totalReserved = 0;
        foreach ($rows as $r) {
            $totalOnHand += (int) $r['on_hand'];
            $totalReserved += (int) $r['reserved'];
        }

        return $this->renderLayout('stock/list', array(
            'rows'          => $rows,
            'missing'       => $missing,
            'onlyLow'       => $onlyLow,
            'totalOnHand'   => $totalOnHand,
            'totalReserved' => $totalReserved,
            'orphans'       => StockReport::orphanReservations(),
        ));
    }

    /**
     * Detail rezervaci produktu.
     */
    public function reservationsAction()
    {
        global $db;
        legacy_db();
        $pid = get_param('product');
        $res = StockReport::reservations($pid);
        $rows = array();
        foreach ($res as $orderId => $qty) {
            $o = $db->one("SELECT status, placed_at FROM orders WHERE id = '" . $orderId . "'");
            $rows[] = array(
                'Objednávka' => $orderId,
                'Kusů'       => (int) $qty,
                'Stav'       => $o ? order_state_label($o['status']) : '(neexistuje)',
                'Datum'      => $o ? format_date($o['placed_at']) : '',
            );
        }

        return $this->renderLayout('partials/table', array(
            'heading' => 'Rezervace produktu ' . product_name($pid),
            'columns' => array('Objednávka', 'Kusů', 'Stav', 'Datum'),
            'rows'    => $rows,
        ), 'Rezervace');
    }

    /**
     * Inventura – rucni prepis stavu.
     */
    public function inventoryAction()
    {
        if (is_post()) {
            $qty = post_param('qty', array());
            if (is_array($qty)) {
                foreach ($qty as $pid => $q) {
                    if ($q === '') {
                        continue;
                    }
                    StockReport::setOnHand($pid, (int) $q);
                }
            }
            flash('Inventura uložena');

            return $this->redirect(admin_url('stock'));
        }

        return $this->renderLayout('stock/list', array(
            'rows'          => StockReport::all(),
            'missing'       => array(),
            'onlyLow'       => false,
            'totalOnHand'   => 0,
            'totalReserved' => 0,
            'orphans'       => array(),
            'inventory'     => true,
        ), 'Inventura');
    }
}

