if (!function_exists('legacy_autoload')) {
    function legacy_autoload($class)
    {
        $prefix = 'App\\Legacy\\';
        if (strpos($class, $prefix) !== 0) {
            return;
        }
        $file = __DIR__ . '/' . str_replace('\\', '/', substr($class, strlen($prefix))) . '.php';
        if (file_exists($file)) {
            require_once $file;
        }
    }
    spl_autoload_register('legacy_autoload');
}

