        $env = isset($_SERVER['APP_ENV']) ? $_SERVER['APP_ENV'] : 'dev';
    }
    $url = str_replace('%kernel.project_dir%', $root, $url);
    $url = str_replace('%kernel.environment%', $env, $url);

