public function cancelledPaidOrderRefundsPaidAmount(): void
{
    $order = $this->draftOrder();
    $order->addItem(ProductId::generate(), 2, $this->czk(500_00));
    $order->applyDiscount($this->czk(100_00));
    $order->confirm();
    $order->markPaid();
    $order->releaseEvents();

    $order->cancel('customer request', new \DateTimeImmutable());

    self::assertTrue($order->refund->equals($this->czk(900_00)));
    $events = $order->releaseEvents();
    self::assertInstanceOf(OrderCancelled::class, $events[0]);
    self::assertTrue($events[0]->refund->equals($this->czk(900_00)));
}

